// Correction experiment 2. Harness fix for the stale baseline k1dd1 literal. T5's menu commit, then the menu exit.
// The commit is a-commit (zone 1) and b-commit (zone 2) from accept_table_c3.json.
// Completion status is the callback d0, or the NAND return d0 when there is no
// callback. The save log is not that status: menu.mjs appends the log first.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/save_v2.mjs om-emu
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/zone_session_k1.mjs';
import { applyStep } from '../../ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/observe_c1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/save_v2.mjs om-emu\n');
  process.exit(2);
}

const sourceTable = JSON.parse(readFileSync(
  resolve('ref/analysis/button-af/readiness/t5-afon-button-handoff/scripts/accept_table_c3.json'),
  'utf8',
));
const steps = sourceTable.filter((step) =>
  (step.phase === 'menu-a' || step.phase === 'menu-b')
  && (step.who === 'candidate' || step.who === 'both')
  && step.action !== 'save'
  && step.action !== 'edge'
  && step.action !== 'reopen-base'
  && step.action !== 'reopen-edge');
const ids = steps.map((step) => step.id);
if (new Set(ids).size !== ids.length) throw new Error('duplicate step id');
for (const step of steps) {
  const cells = step.expect && step.expect.readback && step.expect.readback.cells;
  if (cells && Array.isArray(cells.k1dd1)) {
    cells.k1dd1 = [3, 3, 3, 3, 3, 3, 3, 3, 3, 3];
  }
}
writeFileSync(resolve('work/out/save-table-v2.json'), JSON.stringify(steps, null, 2) + '\n');

const NV = 'work/out/nvram-save-v2.json';
const OUT = resolve('work/out/save-v2.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify({ id: row.id, pass: row.pass, problems: row.problems || null }));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function cellView(got) {
  return {
    k90a1: got.cells.k90a1,
    k1dd1: got.cells.k1dd1,
    k99a1: got.cells.k99a1,
    k9a41: got.cells.k9a41,
    k5962: got.cells.k5962,
    home: got.cells.home,
    originally: got.invariant.originally,
  };
}

function judge(step, got, previous) {
  const exp = step.expect;
  const rb = exp.readback || {};
  const problems = [];
  if (exp.assertTitle !== false && got.title !== exp.title) problems.push('title');
  if (got.helpText !== exp.helpText) problems.push('helpText');
  if (got.highlight !== exp.highlight) problems.push('highlight');
  if (got.screen !== rb.screen) problems.push('screen');
  if (got.profile !== rb.profile) problems.push('profile');
  if (got.profileCached !== rb.profileCached) problems.push('profileCached');
  if (!same(got.invariant.k90a1, rb.k90a1)) problems.push('k90a1');
  if (exp.assertFaces !== false) {
    if (got.slotValue !== rb.slotValue) problems.push('slotValue');
    if (got.helpId !== rb.helpId) problems.push('helpId');
  }
  if (exp.assertGlyph !== false && !same(got.glyph, rb.glyph)) problems.push('glyph');
  if (exp.headerHash && got.headerHash !== exp.headerHash) problems.push('header');
  if (rb.cells && !same(cellView(got), rb.cells)) problems.push('cells');
  if (exp.invariant && previous && !same(got.invariant, previous)) problems.push('invariant');
  return problems;
}

function expectedOf(step) {
  const exp = step.expect;
  const rb = exp.readback || {};
  return {
    title: exp.title,
    helpText: exp.helpText,
    highlight: exp.highlight,
    screen: rb.screen,
    profile: rb.profile,
    profileCached: rb.profileCached,
    k90a1: rb.k90a1,
    slotValue: rb.slotValue,
    helpId: rb.helpId,
    glyph: rb.glyph,
    headerHash: exp.headerHash ?? null,
    cells: rb.cells ?? null,
  };
}

function actualOf(got) {
  return {
    title: got.title,
    helpText: got.helpText,
    highlight: got.highlight,
    screen: got.screen,
    profile: got.profile,
    profileCached: got.profileCached,
    k90a1: got.invariant.k90a1,
    slotValue: got.slotValue,
    helpId: got.helpId,
    glyph: got.glyph,
    headerHash: got.headerHash,
    cells: cellView(got),
    screenshot: got.screenshot,
  };
}

async function prepare(ctx) {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  const api = A(0x50ac4afe);
  const brought = ctx.bringUp();
  ctx.emit('behaviour', {
    step: 'bring-up',
    label: 'EMULATOR-ONLY native bring-up 0x6071181e, 0x608fe1b0, 0x609df7e4, task 105. Role: behaviour.',
    ...brought,
  });
  ctx.s.switch_input('lever', 1);
  ctx.s.camapp.pump();
  ctx.idle(500);
  const argument = ctx.l.call(ctx.native(0x604050e5), { d0: 289, d1: 0 }, null, null, 200000).d0 >>> 0;
  ctx.l.call(api, { d0: 289, d1: argument }, null, null, 200000);
  ctx.l.call(api, { d0: 1712, d1: 0 }, null, null, 200000);
  ctx.idle(500);
  const subject = ctx.l.call(ctx.native(0x60063380), { d0: 0x1e71, d1: 0, a0: 0 }, null, null, 200000).d0 & 0xffff;
  if (subject !== 0) throw new Error('subject ' + subject);
  if (ctx.s.get(289) !== 0 || ctx.s.get(25) !== 0) throw new Error('focus');
  return { subject, focus: ctx.s.get(289), active: ctx.s.get(25) };
}

function watchSaves(ctx) {
  const events = [];
  const queue = [];
  const arm = (address, posted) => {
    ctx.l.wrap(address, (prev) => (h, r) => {
      const origAfter = h.finish_after.bind(h);
      const origFinish = h.finish.bind(h);
      h.finish_after = (regs, fn, args) => {
        queue.push({
          posted: true,
          intended: args.d0 >>> 0,
          callback: fn >>> 0,
        });
        ctx.l.observe(fn, (lab, rr) => {
          const job = queue.shift() || {};
          events.push({
            when: 'callback-entry',
            posted: true,
            status: rr.d0 >>> 0,
            intended: job.intended,
            callback: job.callback,
          });
        }, 'obs-save-cb-' + (fn >>> 0).toString(16));
        return origAfter(regs, fn, args);
      };
      h.finish = (regs, args = {}) => {
        events.push({
          when: 'nand-return',
          posted: false,
          status: (args.d0 ?? 0) >>> 0,
          intended: (args.d0 ?? 0) >>> 0,
          callback: null,
        });
        return origFinish(regs, args);
      };
      const before = ctx.l.store_log.nvram.saves.length;
      const out = prev(h, r);
      if (ctx.l.store_log.nvram.saves.length > before) {
        const rec = ctx.l.store_log.nvram.saves[ctx.l.store_log.nvram.saves.length - 1];
        const slot = posted ? queue[queue.length - 1] : events[events.length - 1];
        if (slot) {
          slot.store = rec.store;
          slot.from = rec.from;
          slot.logPosted = rec.posted;
        }
      }
      return out;
    }, posted ? 'EMULATOR-ONLY save-status post' : 'EMULATOR-ONLY save-status write');
  };
  return import(pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href).then((menu) => {
    arm(menu.NAND_WRITE, false);
    arm(menu.NAND_POST, true);
    return { events, queue, menu };
  });
}

function decodeStore(file) {
  const doc = JSON.parse(readFileSync(resolve(file), 'utf8'));
  const out = {};
  for (const name of ['M', 'E']) {
    const raw = Buffer.from(doc[name], 'base64');
    out[name] = {
      bytes: raw.length,
      sha256: createHash('sha256').update(raw).digest('hex'),
      head: raw.subarray(0, 16).toString('hex'),
      raw,
    };
  }
  return out;
}

function readKey(ctx, key, index) {
  return ctx.l.call(ctx.native(0x60063380), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}

async function runMenu() {
  const witnessed = [];
  let queueRef = null;
  const result = await runZone({
    checkout,
    outPath: 'work/out/session-save-v2.jsonl',
    tag: 'save-v2',
    candidate: true,
    help: true,
    rowLabel: true,
    fatalShots: true,
    nvramPath: NV,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    explanation: 'Save procedure. T5 menu commits then menu exits. EMULATOR-ONLY overlay. Role: behaviour.',
    change: 'none in this run; the profile-read overlay is the existing combined change',
    async drive(ctx) {
      const watch = await watchSaves(ctx);
      queueRef = watch.queue;
      witnessed.push(...watch.events);
      const setup = await prepare(ctx);
      emit({
        id: 'save-v2-setup', step: 'setup', pass: true,
        expected: { subject: 0, focus: 0, active: 0 },
        actual: setup,
      });
      const before = ctx.l.store_log.nvram.saves.length;
      let previous = null;
      for (const step of steps) {
        const got = await applyStep(ctx, step);
        const problems = judge(step, got, previous);
        emit({
          id: step.id,
          step: 'key',
          key: step.key,
          action: step.action,
          pass: problems.length === 0,
          problems,
          expected: expectedOf(step),
          actual: actualOf(got),
        });
        if (problems.length) throw new Error(step.id + ' ' + problems.join(','));
        previous = got.invariant;
      }
      ctx.idle(800);
      const log = ctx.l.store_log.nvram.saves.map((rec) => ({
        store: rec.store, from: rec.from, posted: rec.posted,
      }));
      const added = log.slice(before);
      const problems = [];
      if (!added.some((rec) => rec.store === 'M')) problems.push('log-M');
      if (!added.some((rec) => rec.store === 'E')) problems.push('log-E');
      if (watch.events.length < added.length) problems.push('status-missing');
      if (watch.queue.length) problems.push('callback-pending');
      for (const ev of watch.events) {
        if (ev.status !== 0) problems.push('status');
      }
      const byStore = {};
      for (const ev of watch.events) if (ev.store) byStore[ev.store] = ev;
      if (!byStore.M || byStore.M.status !== 0) problems.push('M-status');
      if (!byStore.E || byStore.E.status !== 0) problems.push('E-status');
      emit({
        id: 'save-v2-completion',
        step: 'save',
        pass: problems.length === 0,
        problems,
        expected: { stores: ['M', 'E'], status: 0 },
        actual: { added, events: watch.events, pending: watch.queue.length, screen: ctx.s.screen() },
      });
      if (problems.length) throw new Error('save ' + problems.join(','));
    },
  });
  return { result, witnessed, queueRef };
}

function persistedCells(ctx) {
  return {
    zone: ctx.readByte(0xa031e920),
    zoneCached: ctx.readByte(0x6031e920),
    subject: readKey(ctx, 0x1e71, 0),
    dfa1: readKey(ctx, 0xdfa1, 0),
    q9a41: [readKey(ctx, 0x9a41, 0), readKey(ctx, 0x9a41, 1)],
    k1dd1: Array.from({ length: 10 }, (_, i) => readKey(ctx, 0x1dd1, i)),
    k99a1: Array.from({ length: 8 }, (_, i) => readKey(ctx, 0x99a1, i)),
    mirror: Array.from(ctx.l.sim.read(0xa031eeb0, 55)),
  };
}

async function runReopen(file) {
  return runZone({
    checkout,
    outPath: 'work/out/session-save-v2-reopen.jsonl',
    tag: 'save-v2-reopen',
    candidate: true,
    help: true,
    rowLabel: true,
    fatalShots: true,
    nvramPath: NV,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    explanation: 'Read the saved store back. EMULATOR-ONLY overlay. Role: behaviour.',
    change: 'none',
    async drive(ctx) {
      const menu = await import(pathToFileURL(resolve(checkout, 'emu/src/lab/menu.mjs')).href);
      await prepare(ctx);
      const loaded = [...(ctx.l.store_log.nvram.loaded || [])];
      const mirrorMatch = {};
      for (const name of ['M', 'E']) {
        const [addr, size] = menu.STORE_MIRRORS[name];
        const ram = Buffer.from(ctx.l.sim.read(addr, size));
        mirrorMatch[name] = ram.equals(file[name].raw);
      }
      const cells = persistedCells(ctx);
      const shot = ctx.shot('cells');
      const problems = [];
      if (!loaded.includes('M') || !loaded.includes('E')) problems.push('loaded');
      if (!mirrorMatch.M || !mirrorMatch.E) problems.push('file-bytes');
      if (cells.mirror.some((b) => b !== 0xff)) problems.push('mirror');
      if (cells.zone !== 0) problems.push('zone');
      if (cells.subject !== 0) problems.push('subject');
      emit({
        id: 'save-v2-persisted',
        step: 'persisted',
        pass: problems.length === 0,
        problems,
        expected: {
          loaded: ['M', 'E'],
          mirrorMatch: { M: true, E: true },
          zone: 0,
          subject: 0,
          mirror: 'FF',
        },
        actual: {
          loaded,
          mirrorMatch,
          cells,
          mHead: file.M.head,
          eHead: file.E.head,
          mBytes: file.M.bytes,
          eBytes: file.E.bytes,
          mSha256: file.M.sha256,
          eSha256: file.E.sha256,
          screenshot: shot.file ? shot.file.split(/[/\\]/).pop() : null,
        },
      });
      if (problems.length) throw new Error('persisted ' + problems.join(','));
    },
  });
}

emit({
  id: 'save-v2-plan',
  step: 'plan',
  pass: true,
  steps: ids.length,
  commits: ['a-commit', 'b-commit'],
  exits: ['a-exit-0', 'a-exit-1', 'b-exit-0', 'b-exit-1'],
  note: 'Same T5 candidate menu commits and menu exits. No edge sequence in this procedure run.',
});

const menu = await runMenu();
if (!menu.result.ok) {
  emit({ id: 'save-v2-done', step: 'done', pass: false, ok: false, failed: menu.result.failed });
  process.exit(1);
}
const file = decodeStore(NV);
const reopen = await runReopen(file);
emit({
  id: 'save-v2-done',
  step: 'done',
  pass: reopen.ok,
  ok: reopen.ok,
  failed: reopen.failed,
});
if (!reopen.ok) process.exit(1);
